def life_population(grid: list[list[int]], generations: int) -> int:
    # dimensions
    h: int = len(grid)
    w: int = len(grid[0])
    # copy initial grid
    cur: list[list[int]] = []
    for row in grid:
        new_row: list[int] = []
        for val in row:
            new_row.append(val)
        cur.append(new_row)

    # simulate generations
    for _ in range(generations):
        # create next grid filled with zeros
        nxt: list[list[int]] = []
        for _r in range(h):
            zero_row: list[int] = []
            for _c in range(w):
                zero_row.append(0)
            nxt.append(zero_row)

        # compute next state
        for r in range(h):
            for c in range(w):
                alive: int = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr != 0 or dc != 0:
                            nr: int = r + dr
                            nc: int = c + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                alive = alive + cur[nr][nc]
                if alive == 3 or (alive == 2 and cur[r][c] == 1):
                    nxt[r][c] = 1
                else:
                    nxt[r][c] = 0
        cur = nxt

    # count live cells
    total: int = 0
    for row in cur:
        row_sum: int = 0
        for val in row:
            row_sum = row_sum + val
        total = total + row_sum
    return total
